def solution(input_str):
    n, x = map(int, input_str.split())
    ai = list(map(int, input_str.split()[2].split()))
    items = list(range(2, x + 1))
    seen = {}
    for m in range(1, len(ai) + 1):
        # Choose ai[0] as the reference
        base = ai[0]
        is_possible = True
        for summary in range(1, x + 1):
            tmp = summary // base
            if tmp > m:
                is_possible = False
                break
            rem = summary - base * tmp
            if rem % base != 0:
                is_possible = False
                break
        if not is_possible:
            continue
        for i in range(2, n + 1):
            if ai[i - 1] >= base:
                continue
            group = math.ceil(summary / base * base) - math.floor((summary - 1) / ai[i - 1]) * ai[i - 1]
            if group > 1:
                is_possible = False
                break
        if not is_possible:
            continue
        key = (base, summary, *ai)
        seen[key] = True
    possible = list(seen.keys())
    if len(possible) != 1:
        return "-1"
    return str(len({kwargs['base'] for kwargs in possible}))
