    for i, char in enumerate(s):
        if char == '?':
            new1 = [0, 0]
            new2 = [0, 0]
            for j in range(2):
                for k in range(2):
                    val1 = dp[i][j]
                    val2 = dp[i][1 - j]
                    new1[k] = (new1[k] + val1 * val2) % MOD
            dp[i + 1] = new1
