        parts = input().split()
        _, k, m, r, *nodes = parts
        k = int(k)
        m = int(m)
        r = int(r)
        nodes = list(map(int, nodes))

        # Build virtual tree for all nodes (rooted at r)
        tree = [[] for _ in range(n + 1)]
        for node in range(1, n + 1):
            if tree[node]:
                tree[node] += tree[node]
            tree[node] = [node]
            for child in edges[node]:
                if child != r and r not in tree[child] and child != r:
                    tree[node] += [child]

        # For each node, store its distance from r (depth)
        depths = [0] * (n + 1)
        parent = {node: None for node in range(1, n + 1)}
        stack = [(r, 0)]
        while stack:
            node, d = stack.pop()
            depths[node] = d
            parent[node] = stack[0][0] if stack else None
            for child in tree[node]:
                stack.append((child, d + 1))

        # For each node, we move upward from r until it is not in the tree
        # or until it has children.
        excluded_including_root = [False] * (n + 1)
        for node in nodes:
            while True:
                if parent[node] is None:
                    break
                if depths[parent[node]] <= d:
                    break
                parent[node] = parent[parent[node]]
                if depths[parent[node]] <= d:
                    break
                node = parent[node]

            if node != r:
                excluded_including_root[node] = True

        # Use combinatorics for DP
        dp = [0] * (k + 1)
        dp[0] = 1
        for node in nodes:
            group_count = 0
            for x in range(k - 1, -1, -1):
                if dp[x] == 0:
                    continue
                for i in range(1, x + 1):
                    if not excluded_including_root[node]:
                        group_count += dp[x - i]
            dp[x + 1] += group_count
        print(dp[k] if k <= len(nodes) else 0)

